args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Who_Is_Without_Sin dbr:Lost_in_the_Suburbs }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bdate1. }
  OPTIONAL { ?director dbp:birthDate ?bdate2. }
  BIND(coalesce(?bdate1, ?bdate2) AS ?birthDate)
  FILTER(bound(?birthDate))
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(langMatches(lang(?filmLabel), "EN")) }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(langMatches(lang(?directorLabel), "EN")) }
}
ORDER BY ?birthDate
LIMIT 1

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT ?director ?b1 ?b2 WHERE {
  VALUES ?director { dbr:Raffaello_Matarazzo dbr:Martin_Frič }
  OPTIONAL { ?director dbo:birthDate ?b1. }
  OPTIONAL { ?director dbp:birthDate ?b2. }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
